INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (55, 100, 'Group products introduce', '../', '<p></p><p align="left" style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><strong><span style="color:#009900;font-family:Verdana;font-size:18px;">O</span></strong><span style="color:#009900;font-family:Verdana;font-size:18px;">ur main products diversified followings:</span><br/> <strong><span style="color:#009900;font-family:Verdana;font-size:18px;">1. Flexible plastic packaging film industry</span><br/> </strong><span style="color:#009900;font-family:Verdana;font-size:18px;">1.) BOPP film including BOPP plain film (BOPP flower wrapping film, BOPP tape-grade film, BOPP clothes/bag-grade film, BOPP mini/smaller roll, BOPP Sheets) ,BOPP anti-static film, BOPP capacitor film;</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">BOPP heat sealable film, BOPP tobacco film, BOPP straw film;</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">BOPP matte film; BOPP pearlized film;</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">BOPP thermal laminating film, BOPP tear tape;</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">BOPP anti-fog film, BOPP micro/ macro perforated film;</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">Metallized BOPP film (VMBOPP), silver and golden metallized BOPP, laser</span><span style="color:#009900;font-family:Verdana;font-size:18px;">holographic BOPP film,</span><span style="color:#009900;font-family:Verdana;font-size:18px;">and so on.</span></span></span> <span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">2.) BOPET film including BOPP packing film , BOPET lamination film , BOPET insulation film, BOPET capacitor film, 4.5Microns BOPET thermal transfer film, BOPET sheets, sliver metallized BOPET film and so on.</span></span></span></p> <p align="left" style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><span style="color:#009900;font-family:Verdana;font-size:18px;">3.) CPP film including CPP printing film, CPP laminating film, CPP bag film, retort CPP film , metallized cpp film and so on.</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">4.) BOPA film including BOPA printing and laminating film</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">5.) BOPS film including BOPS window envelop film, BOPS shrinkage film and BOPS sheets.</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">6.) PE film including PE stretch film for pallets packaging of machine /hand use , PE cling film for food wrapping, PE bags,PE zipper and so on.</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">7.) PVC cling film and POF shrink cling film. </span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">8.) Tear tape, tear clip, tape for dates/opening tape, thermal color transfer film.</span></span></span></p> <p align="left" style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <br/></p> <span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''></span></span> <p align="left" style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><br/> <strong><span